package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Rect;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.TextView;import androidx.activity.ComponentActivity;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Native explicit enrollment + silent preview with fake camera and actual generated pixel signatures. */
public final class PictureMatchFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);volatile Activity current;
    static final class Access implements PictureCameraAccess.Port {volatile PictureCameraAccess.Status state=PictureCameraAccess.Status.NEEDED;volatile int requests;public PictureCameraAccess.Status status(Activity a){return state;}public void request(Activity a){requests++;}}
    static final class Camera implements PictureCamera.Port {final View view;volatile PictureCamera.Listener listener;volatile boolean closed=true;Camera(ComponentActivity a){view=new View(a);}public View preview(){return view;}public void start(PictureCamera.Listener listener){this.listener=listener;closed=false;}public void close(){closed=true;}}
    interface Check {boolean ready()throws Exception;}
    void await(String operation,Check check)throws Exception{long deadline=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>deadline)throw new AssertionError("Picture fixture did not reach "+operation);Thread.sleep(30);}}
    View root(){for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.getContext().getPackageName().equals(c.getPackageName()))return view;return null;}
    View find(View view,String label){if(view==null)return null;if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&label.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),label);if(found!=null)return found;}}return null;}
    Rect target(String label,boolean clickable){Rect[] result={null};i.runOnMainSync(()->{View view=find(root(),label);if(clickable)while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect visible=new Rect();if(!view.getGlobalVisibleRect(visible)||visible.width()!=view.getWidth()||visible.height()!=view.getHeight()){view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);return;}if(clickable&&(visible.height()<Design.dp(c,48)||visible.width()<Design.dp(c,48)))return;int[] screen=new int[2];view.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+view.getWidth(),screen[1]+view.getHeight());});return result[0];}
    void frame()throws Exception{CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{View owner=root();assertNotNull("Focused app window",owner);owner.getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner.invalidate();});assertTrue("Committed app frame",commit.await(5,TimeUnit.SECONDS));}
    UiObject2 object(String description)throws Exception{await("visible "+description,()->target(description,false)!=null);frame();UiObject2 view=d.wait(Until.findObject(By.desc(description)),5000);assertNotNull(description,view);return view;}
    void click(String label)throws Exception{await("clickable "+label,()->target(label,true)!=null);frame();Rect bounds=target(label,true);assertNotNull(label,bounds);assertTrue(d.click(bounds.centerX(),bounds.centerY()));}
    boolean ime(){boolean[] visible={false};i.runOnMainSync(()->{View owner=root();WindowInsets insets=owner==null?null:owner.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});return visible[0];}
    void finishInput()throws Exception{if(ime()){assertTrue(d.pressBack());await("closed keyboard",()->!ime());}}
    void shown(String text){assertTrue(text,d.wait(Until.hasObject(By.text(text)),6000));}
    void recreate(String text)throws Exception{Activity before=current;Instrumentation.ActivityMonitor monitor=i.addMonitor(current.getClass().getName(),null,false);try{i.runOnMainSync(current::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}await("recreated focused activity",()->current!=before&&current.hasWindowFocus());shown(text);}
    void capture(String name)throws Exception{i.waitForIdleSync();frame();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"picture-reference-"+name+".png")));}
    @Test public void permissionCancelQualityCapturePreviewRecreationSaveAndReopenStayPrivate()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());PictureCameraAccess.Port oldAccess=PictureCameraAccess.port;PictureCamera.Factory oldCamera=PictureCamera.factory;Access access=new Access();List<Camera> cameras=new CopyOnWriteArrayList<>();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AlarmEditorActivity||a instanceof PictureMatchActivity);assertFalse("Actual challenge is forbidden",a.getIntent().getStringExtra("mode")!=null&&a.getIntent().getStringExtra("mode").equals("challenge"));owned.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try(AlarmSkipFixture f=new AlarmSkipFixture()){try{PictureCameraAccess.port=access;PictureCamera.factory=a->{Camera camera=new Camera(a);cameras.add(camera);return camera;};Alarm initial=f.load();initial.enabled=false;try(Store store=f.open()){store.save(initial);}Activity editor=i.startActivitySync(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",initial.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));await("editor focused",editor::hasWindowFocus);shown("Edit alarm");click("Challenges");click("Configure Picture match");shown("Add a picture reference");click("Save picture reference");assertTrue(object("Picture scan error").getText().contains("Capture"));capture("invalid");click("Allow picture camera");await("one explicit permission callback",()->access.requests==1);assertEquals(1,access.requests);i.runOnMainSync(()->((PictureMatchActivity)current).onRequestPermissionsResult(PictureCameraAccess.REQUEST,new String[]{android.Manifest.permission.CAMERA},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED}));assertTrue(object("Picture scan error").getText().contains("not allowed"));assertTrue(cameras.isEmpty());click("Back");shown("Challenges");assertFalse(f.load().json().has("routine"));click("Configure Picture match");shown("Add a picture reference");object("Picture reference name").setText("Bathroom shelf");finishInput();access.state=PictureCameraAccess.Status.READY;recreate("Add a picture reference");click("Start picture camera");await("owned fake camera started",()->cameras.size()==1&&cameras.get(0).listener!=null);Camera first=cameras.get(0);i.runOnMainSync(()->first.listener.frame(null,SystemClock.elapsedRealtime(),"Use a brighter, textured picture with visible detail."));assertTrue(object("Picture scan status").getText().contains("textured"));click("Capture reference");assertTrue(object("Picture scan error").getText().contains("fresh"));PictureSignature actual=PictureNativeTest.signature();i.runOnMainSync(()->first.listener.frame(actual,SystemClock.elapsedRealtime(),""));click("Capture reference");shown("Reference captured");assertTrue(first.closed);capture("captured");recreate("Add a picture reference");shown("Reference captured");assertEquals("Bathroom shelf",object("Picture reference name").getText());assertEquals(1,cameras.size());capture("recreated");click("Try picture match");shown("Picture match preview");click("Start picture camera");await("new preview fake camera started",()->cameras.size()==2&&cameras.get(1).listener!=null);Camera second=cameras.get(1);i.runOnMainSync(()->{first.listener.frame(actual,SystemClock.elapsedRealtime(),"");second.listener.frame(PictureSignature.from(PictureNativeTest.pixels(93),128,128,0),SystemClock.elapsedRealtime(),"");});assertTrue(object("Picture scan status").getText().contains("Different view"));i.runOnMainSync(()->{long now=SystemClock.elapsedRealtime();second.listener.frame(actual,now-801,"");second.listener.frame(actual,now-400,"");second.listener.frame(actual,now-200,"");second.listener.frame(actual,now,"");});shown("Picture matched");assertTrue(second.closed);capture("matched");click("Return to reference");shown("Add a picture reference");click("Save picture reference");shown("Challenges");click("Save routine");shown("Edit alarm");Activity owner=current;click("Save alarm");await("private editor saved and finished",owner::isDestroyed);assertEquals(1,f.schedules);Alarm saved=f.load();assertFalse(saved.enabled);assertEquals(1,saved.challenges().tasks.get(1).units());assertEquals(actual.key(),saved.challenges().tasks.get(1).picture.key());try(Store store=f.open()){Backup.validate(store.backup());}editor=i.startActivitySync(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",saved.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Activity opened=editor;await("reopened editor focused",opened::hasWindowFocus);shown("Edit alarm");click("Challenges");click("Edit task 2 Picture match");shown("Add a picture reference");shown("Reference captured");assertEquals("Bathroom shelf",object("Picture reference name").getText());access.state=PictureCameraAccess.Status.UNSUPPORTED;recreate("Add a picture reference");shown("No supported camera is available. Use Math instead.");capture("reopened");assertEquals(2,cameras.size());assertTrue(cameras.stream().allMatch(camera->camera.closed));
            }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());d.takeScreenshot(new File(folder,"picture-reference-failure.png"));d.dumpWindowHierarchy(new File(folder,"picture-reference-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});await("all fixture activities destroyed",()->owned.stream().allMatch(Activity::isDestroyed));}}
        finally{app.unregisterActivityLifecycleCallbacks(lifecycle);PictureCameraAccess.port=oldAccess;PictureCamera.factory=oldCamera;}}
}
